mapper.select:
SELECT * FROM question_test_record
WHERE user_id = #{userId} AND section_id = #{sectionId}
ORDER BY create_time DESC

SELECT * FROM question_test_record
WHERE test_batch_no = #{testBatchNo}
ORDER BY question_id ASC

SELECT test_batch_no AS testBatchNo, section_id AS sectionId, COUNT(*) AS totalQuestions, SUM(CASE WHEN is_correct = 1 THEN 1 ELSE 0 END) AS correctQuestions, SUM(CASE WHEN is_correct = 0 THEN 1 ELSE 0 END) AS wrongQuestions, ROUND(SUM(CASE WHEN is_correct = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) AS accuracyRate, MIN(create_time) AS startTime, MAX(create_time) AS endTime FROM question_test_record WHERE user_id = #{userId}
AND section_id = #{sectionId}
GROUP BY test_batch_no, section_id ORDER BY create_time DESC

SELECT * FROM question_test_record WHERE user_id = #{userId} AND is_correct = 0
AND section_id = #{sectionId}
ORDER BY create_time DESC

